    /// <summary>
    /// What the dialog says when the export ran to completion but produced fewer files than the user
    /// selected sessions. The count is in the message because "some of your sessions are missing" is
    /// only actionable if the user can see how many landed — and because the destination shown
    /// underneath it may well contain files from an earlier, complete export.
    /// </summary>
    /// <param name="exported">Sessions that produced a CSV.</param>
    /// <param name="requested">Sessions the user selected.</param>
    /// <param name="missing">How many of the shortfall were already gone from the database, as
    /// opposed to present but empty. Named separately because the two are different things to a user
    /// hunting for a file that is not there: a session deleted while the dialog was open is not a
    /// session with no rows in it, and reporting the second when the first happened sends them
    /// looking through data that was never the problem.</param>
    private static string DescribeShortfall(int exported, int requested, int missing)
    {
        if (requested == 0) { return "Nothing was exported: no sessions were selected."; }

        var lead = exported == 0
            ? "Nothing was exported"
            : $"Exported {exported} of {requested} sessions";

        // Agreement done by hand rather than with a "(s)": this string is read by someone who has
        // just been told their export did not fully happen, and that is the wrong moment to look
        // sloppy about how many of their sessions are gone.
        var goneSessions = missing == 1 ? "1 session is" : $"{missing} sessions are";

        return missing switch
        {
            0 when exported == 0 => $"{lead}: no logged data was found.",
            0 => $"{lead}: the rest had no logged data.",
            _ when missing == requested - exported => $"{lead}: {goneSessions} no longer in the database.",
            _ => $"{lead}: {goneSessions} no longer in the database, and the rest had no logged data.",
        };
    }

    /// <summary>
    /// One session mapped to the file it will be written to.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.ExportTarget
    private sealed record ExportTarget(int SessionId, string Filepath);

    /// <summary>
    /// Resolves the destination file for every selected session up front, so the export can be
    /// pre-flighted before any data is written. Per-session file naming only applies when writing
    /// into a directory (multi-session export, or the directory-layout test hook); a plain
    /// single-file export writes straight to <see cref="ExportFilePath"/> and so doesn't depend on
    /// LoggingManager. Sessions no longer in the in-memory list fall back to "Session_{id}".
    /// </summary>
    /// <remarks>
    /// Materialising every target here is also what makes the export's promise — N selected
    /// sessions produce N files — enforceable, so the shared <see cref="ExportFileNamer"/> that
    /// keeps two sessions off one path lives on this loop. Without it, two rows sharing a name
    /// resolved to the same path and the second write truncated the first, silently, under an
    /// "Export complete" (issue #186).
    /// </remarks>
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.ResolveExportTargets
    private List<ExportTarget> ResolveExportTargets()
    {
        var targets = new List<ExportTarget>(_sessionsIds.Count);
        var perSessionFiles = _forceDirectoryLayout || _sessionsIds.Count > 1;
        var namer = new ExportFileNamer();

        foreach (var sessionId in _sessionsIds)
        {
            string filepath;
            if (perSessionFiles)
            {
                filepath = namer.NextCsvPath(ExportFilePath, _sessionNameLookup(sessionId), sessionId);
            }
            else
            {
                filepath = ExportFilePath;
            }

            targets.Add(new ExportTarget(sessionId, filepath));
        }

        return targets;
    }

    /// <summary>
    /// Returns a user-facing reason why <paramref name="filepath"/> cannot be written, or null when
    /// it looks writable. Only an existing file is probed, and the probe never truncates or creates
    /// anything, so a blocked export leaves the destination untouched.
    /// </summary>
    /// <remarks>
    /// <para>The probe asks for exactly what the export itself asks for — <see cref="FileAccess.Write"/>
    /// with <see cref="FileShare.Read"/>, the mode <c>StreamWriter</c> uses in
    /// <c>OptimizedLoggingSessionExporter.RunExport</c>. Anything stricter predicts failures the real
    /// write would not hit: with <see cref="FileShare.None"/> a destination merely being *read* by
    /// another program failed the probe while <c>StreamWriter</c> went on to succeed, which would have
    /// aborted a perfectly good export.</para>
    /// <para>Measured on macOS 26, holder vs. probe: a reader (either share mode) passes the probe and
    /// the write; an exclusive writer — the "still open in Excel" case this exists for — fails both.
    /// A chmod-444 destination raises <see cref="UnauthorizedAccessException"/>. So the probe is
    /// meaningful off Windows, though not exhaustive: Unix has no mandatory locking, so a non-.NET
    /// program holding the file goes undetected and is caught by the write itself.</para>
    /// </remarks>
    /// <param name="filepath">Destination to probe.</param>
    /// <param name="error">The exception the probe caught, so the caller can log it with its stack
    /// trace; null when the destination looks writable.</param>
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.DescribeUnwritableDestination
    private static string? DescribeUnwritableDestination(string filepath, out Exception? error)
    {
        error = null;

        try
        {
            if (!File.Exists(filepath)) { return null; }

            using var probe = new FileStream(filepath, FileMode.Open, FileAccess.Write, FileShare.Read);
            return null;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            error = ex;
            return DestinationFailureClassifier.Describe(ex, filepath, EXPORT_FILE);
        }
    }

    /// <summary>
    /// The production name source: the session list the Logged Data pane binds to.
    /// </summary>
    private static string? SessionNameFromLoggingManager(int sessionId) =>
        LoggingManager.Instance.LoggingSessions.FirstOrDefault(s => s.ID == sessionId)?.Name;

    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.GetLoggingSessionFromId
    private async Task<LoggingSession?> GetLoggingSessionFromId(int sessionId)
    {
        await using var context = _loggingContext.CreateDbContext();
        var loggingSession = await context.Sessions
            .AsNoTracking()
            .Where(s => s.ID == sessionId)
            .Select(s => new LoggingSession
            {
                ID = s.ID
            }).FirstOrDefaultAsync();
        return loggingSession;
    }
    #endregion

    #region Test Hook
    /// <summary>
    /// UI-test entry point: exports the configured session(s) straight into
    /// <paramref name="directory"/> — one <c>{session}.csv</c> per session — using the same
    /// exporter and the dialog's default options (all samples, absolute time), with no
    /// <c>SaveFileDialog</c>/<c>FolderBrowserDialog</c>. Wired only through the
    /// <see cref="Daqifi.Desktop.Common.AppDataPaths.TestExportPath"/> hook, so production
    /// export behaviour is unchanged. Awaitable so the harness can know when the file is on disk.
    /// </summary>
    /// <param name="directory">Destination directory (created if missing) the harness owns.</param>
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.ExportToDirectoryAsync
    internal Task ExportToDirectoryAsync(string directory)
    {
        Directory.CreateDirectory(directory);
        _forceDirectoryLayout = true;
        ExportFilePath = directory;
        return ExportLoggingSessionsCommand.ExecuteAsync(null);
    }
    #endregion

    #region IDisposable
    /// <summary>
    /// Cancels and releases the export cancellation source. Called by <c>ExportDialog</c> when the
    /// dialog window closes, so a dialog dismissed mid-export does not leak the token source (and its
    /// registrations) for the lifetime of the process.
    /// </summary>
    // @port: Daqifi.Desktop.ViewModels.ExportDialogViewModel.Dispose
    public void Dispose()
    {
        var cts = _cts;
        _cts = null;
        if (cts != null)
        {
            try
            {
                cts.Cancel();
            }
            catch (ObjectDisposedException)
            {
                // Already disposed by the export's finally block — nothing left to cancel.
            }

            cts.Dispose();
        }

        GC.SuppressFinalize(this);
    }
    #endregion
}
